<?= $this->extend(PHARMACY_VIEW . 'layout') ?>
<?= $this->section('main-content') ?>
<main class="dashboard-container pharmacy-delivery-page" aria-labelledby="pharmacy-delivery-title">
    <?= $this->include(PHARMACY_VIEW . 'pages/delivery/_toolbar') ?>
    <section class="pharmacy-delivery-grid" aria-label="Delivery records">
    <?php if (($rows ?? []) === []): ?><div class="card pharmacy-delivery-empty" role="status"><i class="bi bi-truck d-block" aria-hidden="true"></i><strong>No delivery records found</strong><span>Adjust the search or filters.</span></div>
    <?php else: foreach ($rows as $row): ?>
        <?php $orderStatus = (string) ($row['order_status'] ?? ''); $orderClass = $orderStatus === 'cancelled' ? 'danger' : ($orderStatus === 'fulfilled' ? 'success' : 'warning'); $paymentStatus = (string) ($row['payment_status'] ?? ''); $paymentClass = $paymentStatus === 'paid' ? 'success' : (in_array($paymentStatus, ['failed', 'refunded'], true) ? 'danger' : 'info'); $deliveryStatus = trim((string) ($row['delivery_status'] ?? '')); $deliveryMissing = $deliveryStatus === '' || strtolower($deliveryStatus) === 'not recorded'; $deliveryClass = $deliveryMissing ? 'light' : (in_array($deliveryStatus, ['failed', 'returned'], true) ? 'danger' : ($deliveryStatus === 'delivered' ? 'success' : 'warning')); $address = trim((string) ($row['delivery_address'] ?? '')); $addressSummary = $address === '' || strtolower($address) === 'not recorded' ? 'Not recorded' : mb_strimwidth($address, 0, 70, '…'); ?>
        <article class="card pharmacy-delivery-item">
            <header class="delivery-card-header"><div class="min-width-0"><span class="delivery-card-eyebrow">Delivery order</span><h2 class="h6 mb-1 delivery-value" title="<?= esc($row['order_number'], 'attr') ?>"><?= esc($row['order_number']) ?></h2><div class="delivery-card-meta"><span><?= esc($row['created_at']) ?></span><span>Prescription: <?= esc($row['prescription_number']) ?></span></div></div></header>
            <section class="delivery-card-section delivery-card-patient" aria-label="Patient"><span class="delivery-card-label">Patient</span><strong class="delivery-value" title="<?= esc($row['patient_name'], 'attr') ?>"><?= esc($row['patient_name']) ?></strong><div class="delivery-card-meta-list"><span class="delivery-meta"><?= esc($row['patient_number']) ?></span><span class="delivery-meta"><?= esc($row['patient_mobile']) ?></span></div></section>
            <section class="delivery-card-section delivery-card-contact" aria-label="Contact and address"><div><span class="delivery-card-label">Delivery contact</span><strong class="delivery-value"><?= esc($row['delivery_contact']) ?></strong></div><div><span class="delivery-card-label">Address summary</span><span class="delivery-meta delivery-wrap" title="<?= esc($address, 'attr') ?>"><?= esc($addressSummary) ?></span></div></section>
            <section class="delivery-card-section delivery-card-delivery" aria-label="Delivery details"><div><span class="delivery-card-label">Provider</span><strong class="delivery-value"><?= esc($row['provider']) ?></strong></div><div><span class="delivery-card-label">Tracking reference</span><span class="delivery-meta delivery-wrap"><?= esc($row['tracking_reference'] === 'Not recorded' ? '—' : $row['tracking_reference']) ?></span></div><div><span class="delivery-card-label">Delivery dates</span><span class="delivery-meta">Dispatched: <?= esc($row['dispatched_at'] ?: '—') ?></span><span class="delivery-meta">Delivered: <?= esc($row['delivered_at'] ?: '—') ?></span></div></section>
            <section class="delivery-card-section delivery-card-statuses" aria-label="Statuses"><div><span class="delivery-card-label">Order Status</span><span class="badge delivery-status-badge badge-<?= $orderClass ?>"><?= esc(ucwords(str_replace('_', ' ', $orderStatus ?: 'Unknown'))) ?></span></div><div><span class="delivery-card-label">Payment Status</span><span class="badge delivery-status-badge badge-<?= $paymentClass ?>"><?= esc(ucwords(str_replace('_', ' ', $paymentStatus ?: 'Unknown'))) ?></span></div><div><span class="delivery-card-label">Delivery Status</span><span class="badge delivery-status-badge badge-<?= $deliveryClass ?>"><?= esc($deliveryMissing ? 'Not recorded' : ucwords(str_replace('_', ' ', $deliveryStatus))) ?></span></div></section>
            <footer class="delivery-card-footer"><?= view(PHARMACY_VIEW . 'pages/delivery/_actions', ['row' => $row]) ?></footer>
        </article>
    <?php endforeach; endif; ?></section>
    <?= $this->include(PHARMACY_VIEW . 'parts/delivery_pagination') ?>
</main>
<?= $this->include(PHARMACY_VIEW . 'pages/delivery/_modal') ?>
<?= $this->section('scripts') ?><?= $this->include(PHARMACY_VIEW . 'pages/delivery/_scripts') ?><?= $this->endSection() ?>
<?= $this->endSection() ?>
